// =========================================================
// PARSE INCOMING + DETERMINE SESSION STATE
// =========================================================

const msg = $('📡 Telegram Trigger').first().json.message;
const adminChatId = msg.chat.id.toString();

// Detect incoming content type
const rawText     = msg.text || '';
const hasPhoto    = !!msg.photo;
const hasVideo    = !!msg.video;
const hasDocument = !!msg.document;
const hasAudio    = !!(msg.audio || msg.voice);
const caption     = msg.caption || '';

let contentType = 'none';
if (rawText && !hasPhoto && !hasVideo && !hasDocument && !hasAudio) contentType = 'text';
if (hasPhoto)    contentType = 'photo';
if (hasVideo)    contentType = 'video';
if (hasDocument) contentType = 'document';
if (hasAudio)    contentType = 'audio';

// Get highest-res file_id for media
let fileId = null;
if (hasPhoto)    fileId = msg.photo[msg.photo.length - 1].file_id;
if (hasVideo)    fileId = msg.video.file_id;
if (hasDocument) fileId = msg.document.file_id;
if (hasAudio)    fileId = (msg.audio || msg.voice).file_id;

// Find active session for this admin
const sessions = $('📋 Read Session Tab').all();
const activeSession = sessions.find(s =>
  s.json.admin_chat_id === adminChatId && s.json.status === 'active'
);

const currentStep = activeSession?.json?.step || 'new';

// Detect special commands
const textLower = rawText.toLowerCase().trim();
const isYes    = ['yes', '/confirm', 'confirm', 'send', '✅ yes send it'].includes(textLower);
const isNo     = ['no', '/cancel', 'cancel', '❌ cancel', 'abort'].includes(textLower);
const isStart  = ['/start', '/broadcast', 'start', 'hi', 'hello', 'hey'].includes(textLower) || currentStep === 'new';

return [{
  json: {
    adminChatId,
    currentStep,
    activeSession: activeSession?.json || null,
    rawText,
    contentType,
    fileId,
    caption,
    isYes,
    isNo,
    isStart,
    isMediaContent: ['photo', 'video', 'document', 'audio'].includes(contentType)
  }
}];

const text = $json.rawText.toLowerCase().trim();
const adminChatId = $json.adminChatId;

const MAP = {
  '1': 'major client', '1️⃣  major clients': 'major client',
  'major client': 'major client', 'major clients': 'major client',
  '2': 'existing client', '2️⃣  existing clients': 'existing client',
  'existing client': 'existing client', 'existing clients': 'existing client',
  '3': 'potential client', '3️⃣  potential clients': 'potential client',
  'potential client': 'potential client', 'potential clients': 'potential client',
  '4': 'past client', '4️⃣  past clients': 'past client',
  'past client': 'past client', 'past clients': 'past client',
  '5': 'all', '5️⃣  all contacts': 'all', 'all': 'all', 'all contacts': 'all'
};

const segment = MAP[text];
if (!segment) {
  return [{ json: { ...($json), parseError: true, adminChatId } }];
}

return [{ json: { ...($json), selectedSegment: segment, adminChatId } }];

const incoming  = $json;
const session   = incoming.activeSession;
const adminChatId = incoming.adminChatId;

if (!session) {
  return [{ json: { error: 'no_session', adminChatId } }];
}

const selectedSegment = session.selected_segment;
const contentType     = incoming.contentType;
const fileId          = incoming.fileId;
const caption         = incoming.caption || '';
const contentText     = incoming.rawText || '';

// Build human-readable preview
let previewLine = '';
if (contentType === 'text')     previewLine = `📝 Text: "${contentText.substring(0, 120)}${contentText.length > 120 ? '...' : ''}"`;
if (contentType === 'photo')    previewLine = `🖼️ Image${caption ? `\nCaption: "${caption}"` : ' (no caption)'}`;
if (contentType === 'video')    previewLine = `🎥 Video${caption ? `\nCaption: "${caption}"` : ' (no caption)'}`;
if (contentType === 'document') previewLine = `📄 Document${caption ? `\nCaption: "${caption}"` : ' (no caption)'}`;
if (contentType === 'audio')    previewLine = `🎤 Voice/Audio message`;

return [{
  json: {
    adminChatId,
    selectedSegment,
    contentType,
    fileId,
    contentText,
    mediaCaption: caption,
    previewLine
  }
}];

// Count how many contacts match the selected segment
// Reads from the pre-fetched contacts passed through
const segment   = $json.selectedSegment;
const adminChatId = $json.adminChatId;

// Fetch contacts inline (in n8n: chain a Google Sheets getAll node before this)
const allContacts = $('📋 Read ALL Contacts — Count').all();

const EXCLUDED = ['do not contact'];

const count = allContacts.filter(item => {
  const c   = item.json;
  const tag = c.Tag?.toLowerCase()?.trim();
  const optOut = c['WhatsApp Opt-Out'];
  const phone  = c.Phone || '';
  if (!phone.trim()) return false;
  if (optOut === 'TRUE' || optOut === true) return false;
  if (EXCLUDED.includes(tag)) return false;
  if (segment === 'all') return true;
  return tag === segment;
}).length;

return [{ json: { ...($json), matchCount: count } }];

// Get session data for this admin
const allSessions = $('📋 Read Session Tab').all();
const adminChatId = $('🧠 Parse Message + Determine Step').first().json.adminChatId;
const session = allSessions.find(s =>
  s.json.admin_chat_id === adminChatId && s.json.status === 'active'
);

const segment    = session?.json?.selected_segment || 'all';
const cType      = session?.json?.content_type;
const cText      = session?.json?.content_text;
const fileId     = session?.json?.media_file_id;
const caption    = session?.json?.media_caption;

const EXCLUDED_TAGS = ['do not contact'];
const allContacts   = $input.all();
const results       = [];

for (const item of allContacts) {
  const c      = item.json;
  const tag    = c.Tag?.toLowerCase()?.trim();
  const optOut = c['WhatsApp Opt-Out'];
  const rawPhone = c.Phone || '';

  // Skip blocked
  if (optOut === 'TRUE' || optOut === true) continue;
  if (EXCLUDED_TAGS.includes(tag)) continue;
  if (!rawPhone.trim()) continue;

  // Segment filter
  if (segment !== 'all' && tag !== segment) continue;

  // Normalize phone to WhatsApp E.164 (digits only, no +)
  let phone = rawPhone.replace(/\D/g, '');
  if (phone.startsWith('0') && phone.length === 11) {
    phone = '234' + phone.substring(1);
  }
  if (phone.length < 7 || phone.length > 15) continue; // invalid

  results.push({
    json: {
      name:          c.Name || 'Contact',
      phone,
      originalPhone: rawPhone,
      tag:           c.Tag,
      segment,
      contentType:   cType,
      contentText:   cText,
      fileId,
      mediaCaption:  caption,
      adminChatId
    }
  });
}

return results;

